applied = skipped = 0
for snippet, new in PAIRS:
    i = t.find(snippet)
    if i == -1:
        print("SKIP(not found):", snippet[:30]); skipped += 1; continue
    if t.count(snippet) > 1:
        print("SKIP(not unique):", snippet[:30]); skipped += 1; continue
    j = t.find("\n\n", i)
    if j == -1:
        j = len(t)
    t = t[:i] + new.strip() + t[j:]
    applied += 1
p.write_text(t, encoding="utf-8")
print(f"applied={applied} skipped={skipped} / {len(PAIRS)}")

han = sum(1 for ch in t if "\u4e00" <= ch <= "\u9fff")
punct = sum(1 for ch in t if ("\u3000" <= ch <= "\u303f") or ("\uff00" <= ch <= "\uffef") or ch in "，。；：！？、（·—…《》“”‘’")
words = len(re.findall(r"[A-Za-z][A-Za-z0-9\-\'\.]*", t))
print(f"han={han} punct={punct} en_words={words} Word近似={han+punct+words}")
print("img markers:", t.count("!["))
print("citations missing:", [i for i in range(1, 23) if f"[{i}]" not in t] or "none")
